  VALUES 
    (293::BIGINT, 'enseña muy bien y muy buen profe en general'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '10'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2026-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'f3cc0e1b3f8e072a32d300401298e89c98ee6699a41c24b1abfb030785e6ab1e'::TEXT, ARRAY[1020]::BIGINT[]),
    (293::BIGINT, '¡Excelente profesor! Como parte de sus funciones, la facultad debería colocarlo como tutor del profesor Canessa. Este último, no entiende la labor de docente y le serviría mucho aprender, aunque ya supera los 50 años nunca es tarde.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2026-01-01T00:00:00+00:00'::TIMESTAMPTZ, '7c9531729ade3b3adcb51acff32045c93ec2bc1932de50fc6e1cd3a2b215ba85'::TEXT, ARRAY[1020]::BIGINT[]),
    (293::BIGINT, 'El mejor profe de elementos sin duda, se pasa facil si se hacen todas las tareas los trabajos y el profe es comprensible y una muy buena persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-14T00:00:00+00:00'::TIMESTAMPTZ, '45b10189a678389d0cbbd661c947981e421a55ed78ff88be17c9cee1ae476e99'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor, con mucho gusto volvería a llevar clases con él, recomendadísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-20T00:00:00+00:00'::TIMESTAMPTZ, '98011261a579fc2f6d6f40b60adf9f8a6cbf8b92e14c0f578b4602f77d16013f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'El mejor profe de elementos. Sus clases siempre son entretenidas y se aprende bastante. No hace exámenes pero sí deja varias tareas y quices de cada tema que no toman mucho tiempo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '6b7050f14914f901afac68c493a20944e60d0726406ded830d69b483f08da8ae'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'Es un muy buen profe, es muy amable y cómico. Sus clases son muy entretenidas a pesar de que este curso es virtual. Es bastante pesada la materia del curso y muchas veces cuesta entenderla, pero el profe siempre está bastante presente para ayudar en cualquier duda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '59735230f05993bdfe3defa6202a65dbf340e20e13107913b2157231598ff9d0'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Es super buen profe, todo lo explica muy claro, da toda la materia. Está super pendiente de los estudiantes. Muy ordenado, muy buenas clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-20T00:00:00+00:00'::TIMESTAMPTZ, '2d3da3250bc888e3431bf28e7573b05aea9c4dea9bf4b4f5a9e50eb39db5f8a0'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Te amo Avilés, best profe, matricule sin importar el curso, él enseña bien todo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, '888cc90b2c17d4b9fa92b5a41bbf9586cad139fa923052c5d7decd2b588a6d43'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Excelente profe, ojalá diera más cursos, explica las cosas con paciencia y de forma interesante, ayuda a todos y cada uno de los estudiantes, y el ambiente de su clase es muy cómodo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-09-12T00:00:00+00:00'::TIMESTAMPTZ, '775652ca8eb508391f75fe1f288235a2104bfcdb44535e45e7fc4412caac3122'::TEXT, ARRAY[1020]::BIGINT[]),
    (293::BIGINT, 'Es un excelente profesor y persona, las clases son super claras y se toma su tiempo para dar ejemplos claros para que el estudiante entienda, además da buena retroalimentación y es super flexible con fechas de entrega.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a545b1ffd2c0ef2d9a0c66f0db5c105b0a35e60943ea07120ffa6e4b08f10938'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor, el mejor de todos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '04285224768042cacc7303d7955b747ba5db22a3109829ae67a9994bd96e5d5b'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor y persona. Matricule con este profesor siempre que pueda, va a ser la mejor decision que haga.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'b29ea4fc94acc73a80d0c11b63f17945602549ab223cb4aca0809f3dcb50b465'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'El curso se puede llevar individual, en parejas o grupos. Son pocas tareas pero largas (40%), 20% quices y 40% dos proyectos. Graba todas las clases, ayuda muchísimo, da tiempo extra y es un ser humano excepcional. Las clases virtuales las intenta hacer más dinámicas pero sin forzar participación.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '3606f291a922458aac03f103b266a6f925d1925a099ea8f4cd13c84d4b65ee1e'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Deja como 10 mil tareas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-04-26T00:00:00+00:00'::TIMESTAMPTZ, '07d2abf282a19ce9671b6fd98a41c23db4ff060ef9e86bc4a251f6431e5642f4'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Este profe es simplemente excelente, no lo piense mucho y matricule con él. Se nota el amor en su trabajo, las clases aunque largas siempre las da con muy buena gana y explica super claro. El curso se hace fácil y bonito con él. Simplemente un gran profe y un amor de ser humano'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2024-01-03T00:00:00+00:00'::TIMESTAMPTZ, '9f591fd2da9a6957ccd2a43f7262d1fa2a3e086b19e9ce2647c224a43a53a66e'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'SÍ HÁGALO SIN DUDA DELE VIAJE NO LO PIENSE'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, '8da22a85db8b758d5b42e96fa42dde286686730d7a9bf2ae10d07ac42f8b6dad'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor, recomendado si quieren llevar la electiva, y la verdad cualquier otro curso con él. Es bastante amable con los tiempos de entrega, ya que si es necesario brinda más días, las evaluación son bastante buenas, solo son tareas y proyectos. Recomendadisimo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'fb1631d0c933f441b5944340e2808115924dca269b2f5857708441ccbdc783ea'::TEXT, ARRAY[1119]::BIGINT[]),
    (293::BIGINT, 'De los mejores profes no solo de compu, si no de todo el Tec. Lo único malo del profe es que no da todos los cursos de compu :/ Por más profes como Zoster y menos profes como Canessa !!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-09-13T00:00:00+00:00'::TIMESTAMPTZ, 'f17696c3c9febba5a0fd446b3aecaf7748d88083ec1ec64d92076a2f980b03b9'::TEXT, ARRAY[1029, 1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor. Sabe explicar muy bien la materia. Deja trabajos semanalmente que lo hacen a trabajar con las estructuras que programa en clase y tener un mejor entendimiento de ellas. Lástima no da toda la carrera.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-13T00:00:00+00:00'::TIMESTAMPTZ, '3c5ab8facee7c30ed794ab14d5ffbacc44407e73ae63d49bd8686534798ac529'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Es súmamente claro, accesible y amable al explicar materia. Las clases son bastante llevaderas y las tareas programadas ayudan mucho a comprender la materia. Bastante cómico y comprensible. Proyectos son una buena evaluación de comprensión de las clases.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, '386166e94b63d168a8322316d776259225957a7611970a788f4b30f37e918b2f'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Profesor totalmente recomendado. Se nota que le apasiona lo que hace y quiere que uno disfrute y realmente aprenda. Si jamás ha programado, es su opción definitiva, se toma el tiempo para explicar los conceptos más sencillos para aquellos que no conocen. Matricule sin duda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a26a8eb648ba336ba1daaf8691ef8d589f926806fae1b3db364ddaa49737deee'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'Es el mejor profesor que he tenido, sus clases son claras y a pesar de que son virtuales, el profe sabe manejarlas de manera excelente. Si fuera por mi, yo matricularia todos los cursos relacionados a computación con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c3f31bb0dc6ff73bf66a3a3647b8950dcbe530fe257a6656db3461cc8167643b'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor, utiliza una aplicación llamada Discord para hacer las clases, Además de que es mas fácil ponerse en contacto con el mediante esa plataforma, 100% Efectivo. Es un profesor muy bueno, inteligente y se nota su pasión por la materia al ver las presentaciones y trabajos que deja.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '38423c02096a59990806c589d7b3e28adc36eaab14cd242d47eb4ab09739e855'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'MauricioGOD, yo no abandoné la carrera gracias al excelente profesor que es Mauricio, me motiva demasiado, ojalá todos fueran así, uno aprende demasiado, las clases son muy cómodas, la retroalimentación, siempre está dispuesto a ayudar, es que no me alcanza el texto aquí para describir a este crack'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5f45a8f931aad7c58370fdff4f7d690557223cf04f7e6f3c7320d313d6a87010'::TEXT, ARRAY[1020, 1022, 1029, 1030]::BIGINT[]),
    (293::BIGINT, 'Lo de este tío no tiene ni pies ni cabeza, es simplemente la definición de perfección aerodinámica. Su manera de explicar sumado a su gran carisma y simpatía han hecho de este semestre una de las experiencias más fructíferas que haya experimentado en el período que llevo como estudiante. Cojonudo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'f95158c70334c4d81de9b30bc0e0414287bc470f9d21bd6d814927c332158bfe'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'Me atrevería a decir que es el mejor profe de compu. La verdad si tienen la oportunidad de llevarlo con él, ni lo duden. Actualmente quedan muy pocos profes como él, se aprende bastante y se pasa el curso sin problemas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, '471674180d981b1159583f3d63875288ac17500b3dcc4e67a89431d3fba0af83'::TEXT, ARRAY[1020, 1022, 1030, 1029]::BIGINT[]),
    (293::BIGINT, 'Muy buena gente, la verdad recomendadísimo; los trabajos son facilillos, se pueden hacer en parejas y explica muy bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-06-06T00:00:00+00:00'::TIMESTAMPTZ, '9cef6e27091d8110d74267d6b87a53b2d081760a47f7eea8116277520e5812fd'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'Súper recomendado, de los mejores profe que he tenido, ojala todos fueran así. Con él, el curso no se siente para nada pesado y se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'eeeb1cf1cc65b94c459291410e0a4f27db3f54e42c21e29f0f9e7dbf2efe9d24'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'MauricioGOD'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-14T00:00:00+00:00'::TIMESTAMPTZ, 'fd26523a37a15e9a3b9b2062e6cbb7d9bc5cbc6c67f8fa3ec0a041be26337179'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2023-04-24T00:00:00+00:00'::TIMESTAMPTZ, '54af8f3aac166cad0c82b3881e40026c5bad323dd95e85faa184f3885fbcf9b3'::TEXT, ARRAY[1249]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-25T00:00:00+00:00'::TIMESTAMPTZ, 'e6e4e2529d8ce393873c86a11101954b35880dd3e5eb7594fc9d149bc55fd9f0'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-09-28T00:00:00+00:00'::TIMESTAMPTZ, '8630087c9fe475faa3ebfcd32dae7d6ec5cdbaad55a1b2d00c422572401c3db4'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor, ninguna queja, si puede matricular con él ni lo dude.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8138d45553088d622cd506cb180d11f5771b32e3792b9713ab5ddf08eab281a6'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Me atrevo a decir que es el mejor profesor de toda la Escuela de Compu, como persona y como profesor es excelente. Si pueden meter con él algún curso HAGANLO.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '1a4bdc2ef5d043b444d7fa3e912b0e44d3a859b1c8ebd2b2dac1bbfc2192f6d5'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Si tienen la oportunidad de matricular con el, en cualquier curso, háganlo. Sus clases son divertidas, provechosas, excelentes. Es el mejor profesor con el que me he topado. Siempre de verdad que siempre tiene tiempo para sus estudiantes. Hasta en sus días libres saca tiempo para atender dudas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '67101ee2552226b9e4648b5dded2faf27e6d808cf2e8dd2cfc366130f59d37d1'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Definitivamente excelente profesor, me atrevería a decir que el mejor profe que tiene la Escuela de Compu. Clases increíbles, súper entendibles, divertidas, y hacen que uno ponga atención ya que son cero aburridas. Recomendadísimo?'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-25T00:00:00+00:00'::TIMESTAMPTZ, '65475b5dd2b0395c3dadc3bc521d22c11ed3c3ba284f538d9bb570e9c45d7489'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor, aunque por verle casi no prestaba atención a la presentación jaja. (Es muy guapo). Es muy carismático, ayuda mucho a los estudiantes y siempre está atento a las dudas en clase, las responde con mucha amabilidad. Definitivamente matriculen con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Clases excelentes']::TEXT[], '2022-02-25T00:00:00+00:00'::TIMESTAMPTZ, '462938553bd06d0de2032d0a2024fb60c37e96787b7f723758dd6ab621bf16db'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Un excelente profesor, explica increíble, hace que las clases sean divertidas y que a pesar de los trabajos y clases largas es una experiencia buenísima y un ambiente increíble, recomendado totalmente el zoster'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, '1607188abd5f55bcfaeccb16c66c1e9dbb1388fe96bdaeea0497e30786652f75'::TEXT, ARRAY[1029, 1020, 1022]::BIGINT[]),
    (293::BIGINT, 'El mejor profesor sin ninguna duda, siempre ayuda cuando se tiene alguna duda, explica muy bien, siempre dispuesto a explicar otra vez si así se necesita. En los proyectos y tareas ayuda cuando se tiene dudas, las revisiones es bastante estricto pero muy comprensivo. Sin duda de los mejores profes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, '2edcf7fbdbaccf7cb0dd9d5dac64b9b01d05e5d3d9e776b9212ba5ea1626cdba'::TEXT, ARRAY[1020, 1022, 1029]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor sin duda, las clases suelen ser extensas pero sumamente provechosas. Explica todo con mucha claridad y se nota su interés por el estudiante y su aprendizaje. ¡Súper recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-12T00:00:00+00:00'::TIMESTAMPTZ, '896faced23ae5e44e90b3f1706ea04c394d80caa7809f1ce697a171362e7900a'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Es simplemente excelente, es el mejor tanto para cualquier curso, definitivamente la universidad necesita más profesores como él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '5ff3ed9add3185fc439966a375767bc39f289f8d1fab71d1d8db4c1c44bf6abf'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Es muy buen profesor. Siempre dispuesto a ayudar, se preocupa por que el estudiante aprenda, sus clases son muy interesantes y divertidas. Sin duda volvería a matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '0aa3051b86f97370926422754ed1ed26b70a48f86d2769db2f5c8f14d2eca41f'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Uno de los mejores profesores de programación que he tenido, sus clases son muy completas y se interesa mucho porque el estudiante entienda y logre las cosas. Sus trabajos son a un nivel adecuado y da buena retroalimentación. Si tiene la oportunidad matricule con él, es un excelente profesor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '2a25e78295fa6b44276091f1f823f7e82a883e21c8f912fc22570424fc5f8819'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Un profesor súper excelente, si puede llevar un curso con él, no lo dude! Se preocupa por uno, es súper divertido, buena nota, flexible, las evaluaciones que deja son claras y fáciles de hacer si ha asistido a las clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-14T00:00:00+00:00'::TIMESTAMPTZ, '9d4297197408e5a54a8d0ae9e443aa6573a8720de72d8d8d00daf2dbda896bfc'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Lo considero el mejor profe del TEC. Se preocupa por el estudiante, le interesa que usted aprenda. Además es flexible con entregas y aclara dudas en todo momento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, '7dca8734d9f2f113af65c36fa7777936e9f43801e4250ef68288e737f6e6e1a4'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Excelente profe, siempre está disponible y dispuesto a contestar dudas. Da suficiente tiempo para los trabajos y las clases son entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-07-04T00:00:00+00:00'::TIMESTAMPTZ, '52d3fc65fe0541e13d570d0e293df41b8c7082f01ef7dba3df158cd36218d35b'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Clases cómicas y con explicaciones muuuy claras. Siempre está disponible para ayudar al estudiante, y deja varias tareas bastante fáciles que ayudan a comprender la materia. Da gusto recibir clases con él, de los mejores profes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '01430dab14e3373369d6249c0f83c85a3e82a051bef58c3adc5e03439bd7b079'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Es un muy buen profe, todo lo explica súper bien, deja tareas semanalmente, pero son de hacer modificaciones en código que se hizo en clase y si uno tiene dudas u ocupa ayuda siempre saca el tiempo para atenderlo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '380689cfe39013b085420914a47842511a9f988c3aa0904d2fddc2d19c3dd47e'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'El mejor profe de computación. Explica cualquier tema de una forma sencilla. El curso está muy bien organizado. Deja bastantes tareas, pero con buen tiempo. Es comprensivo con plazos de entrega, evalúa justo, las rúbricas son claras y siempre responde las consultas. El mejor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '765e1def850f5a3e3916be8dfd547af86bcf4273695943f041a96937e3a5496d'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Es sin duda de los mejores profesores que tiene el TEC en cuanto a computación, excelente persona, brinda ayuda a la hora que sea y siempre explica de una manera cómica y excelente. Sin duda llevaría todos los cursos de carrera con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'd47f208214be13ea5d8ebe2ffd015046c45b93d812b7f7d62975f161f5e22037'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Un profesor excelente. Sin importar el tema que esté enseñando, explica súper bien, siempre se preocupa que los estudiantes comprendan. Deja una cantidad comprensible de trabajos. Siempre está disponible para ayudar, cuando uno tiene alguna consulta. 100% recomendado, excelente profesor y persona.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '95935496c0f594cd777c542b1af0ebf8cc70b82d56806fc716018a1c77f0bc7d'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Mejor profe que he tenido en mi vida. Todos los profes deberían ser como él. Explica súper claro y lo ayuda a uno a entender la materia y es muy buena gente. Bromea con todo el mundo pero al mismo tiempo da las clases súper bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '03e71f3efb2160eb9dfe525a897547a4c27e00ef07000cbcaa5f87f9e16e78e6'::TEXT, ARRAY[1020]::BIGINT[]),
    (293::BIGINT, 'Si tienen la oportunidad de llevar un curso con él haganlo. Es un excelente profe y más allá una excelente persona. Se preocupa mucho por enseñar y crea un ambiente super ameno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-16T00:00:00+00:00'::TIMESTAMPTZ, '8a7a3577ccc16ca91f8650bcea02f2365954ff4e5624d7c0ecae489c8b86a361'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor, siempre que vea un curso disponible con él, dele, es de esos profes que se nota que le gusta enseñar y que el alumno aprenda'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2019-12-12T00:00:00+00:00'::TIMESTAMPTZ, '1e9a5cfdd109478af22a7ac35a899a2427ccd43dc1a32217ab70376535261d95'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Explica los temas del curso con gran claridad, y promueve un clima de confianza entre él y sus estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '31abb8c3c204574cd2916cafd362bae6a4b97694155bc1dd331e56608da36542'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Es sin duda god tier del TEC, cualquier curso de la carrera que pueda llevar con él, ni lo piense dos veces.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '6373862eb813e7c393a4ce252ee73eadc1659c6b6095092a2fb0b5653ed2d245'::TEXT, ARRAY[1119]::BIGINT[]),
    (293::BIGINT, 'Uno de los mejores profesores que uno se puede topar cuando viene empezando la universidad, bastante amable, respetuoso, comprensivo y compasivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'a524c55bf1cbc7c0349835562a6c0e8cf99bb6b435ec280b6e20e6a6ebf6b79f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-08-28T00:00:00+00:00'::TIMESTAMPTZ, '43a9e9eff4989d146e60f3bd2928d6d796a0919b152e29a548197e9be3c9a1a5'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (293::BIGINT, 'Excelente Servicio: ????? xD Excelente profesor, explica exageradamente bien, las tareas y proyectos son con base a lo visto en clase, si tienes dudas te va a ayudar sin pensarlo y te va a explicar algo las veces que sea necesario, las clases son bastante agradables. No lo dude, matricule con él xD'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6d114ec56bb9e43da50fc052f2e2185c0ad015007ee3c343aefaa3e36afa6d05'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, '42c9c2b655293df99adecd7fe02e9a425857d5255721426aa7660bfde70ded50'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Si pudiera recibir todas las clases de la carrera con él lo haría, un crack en todo el sentido de la palabra, ayuda, siempre disponible y sobretodo muy responsable con revisar los trabajos que deja.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7164bea391522d98b436bee09e8b31099683cee65ded122911a4029f9396e535'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Uno de los mejores profesores que he tenido. Ayuda mucho para resolver dudas con la progra, los examenes son de marque con equis y faciles. El curso en si es muy duro pero el profe hace todo lo que pueda para que las clases sean entretenidas y para asegurarse de que los estudiantes aprendan.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, '12bba89e1072f9ecc7ab7c34e5ac55fa2aa54c1e5424ac52a10745e814085925'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Lo llevé por segunda vez y me gustó mucho más este profe. Clases ordenadas y llenas de chistes, deja todo bien claro, exámenes relativamente fáciles de marque con equis, progras tuanis... Es muy carismático. No es un curso fácil pero con él se disfrutó.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '700c93a6ac20f91cbdb2277a3fb9e6ed6f55357dbaf2c7ed334e41e9baa2bf34'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Matriculen todo lo que puedan con este profe. Es el mejor para los primeros ingresos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-18T00:00:00+00:00'::TIMESTAMPTZ, '2be67c85f2746176c25e4ab840119bc610119ea4fae1a92536d11ddd6426549e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Lo amo solo eso puedo decir, si pueden tomen la clase con el.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, '4e99a46754439314eb46a9e8fe2633333c3ee18c027b8112adb095bac6ae7835'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (293::BIGINT, 'Explíca súper bien, hace las clases interesantes y siempre brinda ayuda aunque sea tardísimo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-08T00:00:00+00:00'::TIMESTAMPTZ, '2a2eb9bb73575fd574d9f61a358f54615bc1dacf17d4202432faae088ff5d8c5'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'db6e59906258ee9099a7c682b851160f3f72112f3cb5981f917f1e012076c2b0'::TEXT, ARRAY[1020]::BIGINT[]),
    (293::BIGINT, 'Es un poco aburrido, pero, más que todo por la materia de poo. Muy guapo por cierto, demasiado, me distraía mucho eso :3'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a04f14eac6e3e23609ea200647494f313c8a8acd8664b93a1d11ff0e01390a2c'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Uno de los mejores profes de San José, se aprende un montón y es bastante fácil pasar mientras que haga todas las tareas. Súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '529d73e89862d5204510d1b4a60ce5aa543536990e46851255387316a7cfca96'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Simplemente el mejor profesor para llevar este curso, si alguna vez diera algo más allá de Estructuras en computación, no dudaría ni un segundo en meter con el el curso, simplemente es excelente, explica demasiado bien, nos brinda código y lógica en clase y en las tareas se agrega a lo de la clase.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'faa05f311c8c4056232ad3c3dc7e5b20e0d91640c30ae73b57ec3984bda755cb'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a25d670f14c1f8d3dc3394f0ede4d1191f47dfd41a76af06f29d1111b5065375'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'De los mejores profesores, agradezco mucho haber tenido una clase con él, muy gracioso, explica excelente, y ayuda en cualquier problema que uno tenga.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, '43c50a83db5fc0b3288b2cdbf05d65527259ba978bf7b266aea32c50cbb0128a'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Excelente profe. Distribuye bien la nota entonces con trabajar durante el semestre se va ganando la nota y no peligra al final. Bastante organizado. Clases excelentes donde explica cosas que son importantes que otros profe no dicen. Siempre dispuesto a ayudar y muestra interés en los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'de6605f4aebed6e93c8fd46e3d6bce3c498bdb8d365fcf4c14f8fbe41d6fd572'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Excelente para primeros ingresos'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, '6314113b0bc7313cebd421a805ab70af85ba5b158fe6f03eaffd61ea99566fd4'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-21T00:00:00+00:00'::TIMESTAMPTZ, '5da5309b97db854d47e3c50709b33c851027fce644ee847b8aa50940484719e5'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Muy buen profe, cuando lleve poo con el daba la clase con bastantes diapositivas pero era muy clara la materia y los examenes eran buenos'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-02-12T00:00:00+00:00'::TIMESTAMPTZ, '3814614aa1b1509091f1d0b0cecfd1340c1ffd8a6728cf826b5f138182015bae'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Super buen profe, y el curso de los mejores que he llevado. Siempre atento a ayudar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'b58ff9e6560a6b4d00c96f77d73cb3ce2258ff9863c2e365f7ecbfb295070890'::TEXT, ARRAY[1119]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor, siempre trata de enseñar la mejor forma de hacer las cosas y destaca su interés por los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'efea3721e0506afcc5bfea00e56fdb7650060f2847ac736781d62d201ef0d4c7'::TEXT, ARRAY[1119]::BIGINT[]),
    (293::BIGINT, 'Exc profe, si está en los profes posibles tienen que llevarla con él. Se aprende mucho, califica bien (ni suave ni duro) y siempre muestra interés en enseñar cualquier curso. (he llevado 3 cursos con él y llevaría más)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-21T00:00:00+00:00'::TIMESTAMPTZ, '86593d7b02022f5cb8cf79847d8ceeb5fdb73ec0ed76b01f27386aff5a56ddf0'::TEXT, ARRAY[1119]::BIGINT[]),
    (293::BIGINT, 'Muestra interés en el aprendizaje de los estudiantes y lo refleja en sus clases, pues explica muy bien y atenderá al momento las dudas de los estudiantes. Tareas y exámenes relativamente fáciles pues explica todo en clase. Proyectos son de dificultad intermedia. Recomendadísimo, ¡excelente profesor!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'abdfa2729376b0e5858eef6b99a92fe43abffd6f84ca9c4baf8691ba6270bfcf'::TEXT, ARRAY[1029, 1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '359bfd103717e57b05061b2d082fa49ff15de72b9444347f1c8c4f4d49cb982b'::TEXT, ARRAY[1119]::BIGINT[]),
    (293::BIGINT, 'Demasiado bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '09b5eb5e4f1442e88504c307844514c15b60cf560756d7589fb1088b425b5bab'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Es muy claro con la materia, muy compresible y se aprende mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'd17630fd85bd4b9964a6112bdb57b8d8fb7e24068e7eed79f1f2bf66809c72af'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Como en todos los cursos que da el profe siempre es una clase muy amena, divertida, se aprende mucho, en este curso era 60% tareas, así que eran muchas pero perfectamente realizables, y 40% un proyecto que se podía escoger el tema, el curso se presta para pasarla bien y relajarse programando.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, '941abc00be5977f1a4e63c7e23f0e195e8b006903679023b24721c18a5b86ad5'::TEXT, ARRAY[1119]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '14b488e0418e54866a2128e853d6ecec69adf07d44f05adba8983f754b962396'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Sin duda uno de los mejores profesores en el TEC. Explica muy claro y sus tareas son adecuadas al curso. Ojalá llevara más cursos con él. Nunca se va a aburrir en una de sus clases ya que siempre busca despertar la atención del estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '42a76b76a96944500c50a8145a9b2fd06e78ea960d52ce2e37a79b061d28681c'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Simplemente uno de los mejores profesores de compu; todos los profes deberían ser como él. Es puntual, ordenado, la materia es entendible, no se va a aburrir con él, se aprende bastante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'a3d0eba231023606caaff84349177ba0b910354f6499a21c766987340e7ebd32'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (293::BIGINT, 'Excelente profe, se preocupa por el estudiante ... recomendado'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2016-07-06T00:00:00+00:00'::TIMESTAMPTZ, '5e10cb56c6e932f81ab7ce873cc7df15c660c51808265e7884edc05213468312'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (293::BIGINT, 'Es un excelente profesor. Usa presentaciones para las clases pero trata de mantener la clase despierta poniendo actividades. Los exámenes son justos y normales. Haga todas las tareas y le ira bien. Super recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ef29895b6034009b2b1bce53e85794fa0296acb11a402bd80a315d746c1ff184'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '37222ef3154dc357a3b9faba8b8b165c19ea4c2b3f75b1049489eff714cdd5e2'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor seria genial si diera cursos mas avanzados porque la forma en que explica es excelente, seria bueno que hiciera mas cuestionarios de practica para preparase para los examenes, sin embargo no le encuentro ninguna critica aparte de eso, recomendado al %100.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8681b456f41a85bdf44f97b7a330ec9603a831414f93ed76b7c7bd9b3b03562f'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Una teja de profesor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '7c93bc980c7b50338ee1d156f3cec5124efb182e6efaa0de8ac1ccaa9248b5ee'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Excelente profe. Le importa que los estudiantes entiendan. Es muy buena persona y las clases entretenidas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-19T00:00:00+00:00'::TIMESTAMPTZ, 'b7089f0949990e1681f54004b64bc0e08ad4df68f06f264e4895652aa3b22e7a'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor! Le interesa mucho que el estudiante aprenda, el ambiente de la clase es muy cómodo y entretenido, da la clase muy clara y brinda toda la ayuda que necesités.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'fcf562e3f131a92a9722cc533772b56bf996493484e4d04caa8840660c60320f'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Excelente profe, explica muy bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'aa616057b1beb099a64068657f59195211507eb67dfdee0efaf0be766042ec8d'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Muy buen profe, hace la clase dinamica y muy entretenida, los proyectos que deja son durillos pero nada del otro mundo. Probablemente el mejor profe de la escuela'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'b71bae8338b22c1fe538fa39dc584be2ae3178273d0d15230444d3ccbd01de3d'::TEXT, ARRAY[1253]::BIGINT[]),
    (293::BIGINT, 'De los mejores profes que he tenido, con el se asegura que las clases no van a ser aburridas, aclara las dudas que uno tiene en clase por tanto no es necesario ir a buscarlo despues...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, '2bfa0879fe722d6dc9205f82a6597bcd3f21ff7e5ad01772c4b73935c8424061'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor. Sus clases son super amenas y se aprende mucho con él. Progras de nivel intermedio así como los examenes. Recomendado al 100%.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'e859ed98330f0f45383f38661736602b68c4cb761d6c10d2d48e4701e51f5dd1'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (293::BIGINT, 'Uno de los mejores profes de compu... Super pura vida, califica los trabajos segun al desempeño de la persona. Super animado, didactico y en general: nacio para ser profe, se nota que le gusta lo que hace y eso lo refleja en sus calses.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-13T00:00:00+00:00'::TIMESTAMPTZ, '7c2be2f8ef229353a0a3a28295626346f7d1a8d077385662efba955b5d5529d0'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (293::BIGINT, 'Buen profesor, entiende que la comprensión de la materia no se da solo por el estudiante sino que el profesor tiene mucho que ver. Es respetuoso y tiene sentido del humor, lo recomiendo mucho porque se aprende y si eres responsable te podría ayudar. Espero siga creciendo como persona y como profesor'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-24T00:00:00+00:00'::TIMESTAMPTZ, '28f3d5b8cc0b06e70e321e1ccc5d8b58bddf85b09c2ddcf0f19f404e3a1e0a3d'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (293::BIGINT, 'Profe super pura vida y esforzado por que el estudiante entienda. Clases entretenidas y da la clase muy clara. Muy recomendado!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'a21b7ca3c3b6f40b3bf21c56c028f9b850e434c84fbb1e6ecdb229b3f3535e32'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Un profe muy tuanis, disfruta lo que hace, por lo que se le facilita la interacción con los estudiantes. Las progras se adaptan a lo que ve en clase, hasta cierto punto muy interesantes si se les presta atención, 10o% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, '87a4f496ca7970cc8a23d1161457c1fc18c961820d1b20e980e9ce4615541066'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'De los mejores profesores en la escuela de computación. Además de explicar siempre la materia con claridad, es comprensivo con todos y procura siempre tener conocimientos para fundamentar lo que enseña. Llevé POO y estructuras de datos y logró hacer entretenidas todas las lecciones'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, '35fae2b56ee66e80b6916a91c1b82d51d103c73bff4533e078e63ff7e8ee102d'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor y persona, super recomendado. No se van aburrir, dá las clases super entretenidas y uno como estudiante aprende mucho. El profe se preocupa de que el estudiante entienda y aprenda bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'a2b07fd5135bd9c4f9ae81febf5d7affaded6d2887977ddb635eb09b9e0ff266'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, '306fd21e50ceebc2cbcf57da7a17c155f7a8d2e2d2441ccb9cf073910660f87d'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Excelente profe, ayuda mucho lo cual facilita los trabajos que deja, muy buena persona, las clases son muy entretenidas, 100% recomendado!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, '81840f04b1af82adeb7e38c317b5df75259700e84bd8eaa81d29b36954b8dc72'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Un profesor muy pura vida. Se llega a desarrollar mucha confianza con él. Se aprende bastante. Utiliza presentaciones que a mi nunca me aburrieron. ¡Recomendadísimo!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, '61bdb0b8eced2629e2751bae0fa7f5e4c5f042c432ee1a55406adff43138c8c5'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Es un excelente profesor, realmente se preocupa por que el estudiante aprenda y lo hace de una manera entretenida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, '904861c1737e5ab72a53c727a235ac954a433400796a4932b64409eb3aaf5baa'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Muy buen profesor, explica todo de forma clara y con ejemplos. Las presentaciones pptx no son aburridas. Si usted tiene dudas, desde el primer día genera un ambiente de confianza por lo que usted puede preguntarle y el tratará en la medida de lo posible dejárselo claro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, '0330516576e28a40944b1ff2f66f4d028e416cb77d09bfe692563865ea8616a9'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'ad17b1c7a2c7327b67876f1aade2b184977179878d9e3c4ca7cbfca1b7064e3c'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'c39e764ce1cf1401a806bdd1a0c255e31f58f2943047cab07b0ad3c65975f939'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (293::BIGINT, 'Es un excelente profesor y persona, es una maravilla explicando y siempre tiene una actitud positiva al dar clases. Suele ser bastante cómico en las clases y realmente parece importarle que el estudiante aprenda. 100 % recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '2bf1c2770f9ab33ea44c947b3352f8ca850e19d9d086f1f524ee96c4239b827f'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (293::BIGINT, 'Uno de los mejores profes que he tenido, se aprende mucho aunque sea facil, sobretodo si hacen todas las tareas. El es super pura vida como persona y eso hace las clases muy entretenidas. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '92723dfb15c3fd2300ac07fe9a7abfd3e6954a605e2852d46325f52b215cd46b'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (293::BIGINT, 'El mejor profe que he tenido. Explica súper bien y se preocupa porque uno entienda. Se ve que le gusta dar clases. Las progras son llevaderas y uno aprende. Los exámenes no son tan pesados. Deja bastantes tareas cortas que lo mantienen a uno al día. Las clases son entretenidas. Súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, '1132823c49401190c41b591195b2eecb75cd1d3eafe90432817e456bb34dc750'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-13T00:00:00+00:00'::TIMESTAMPTZ, '5eb4bf2da7612e474393e927b146a1df5715958df22f3c62ed0c16d865512aa1'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Hasta el momento es el mejor profesor que he tenido, explica hasta que verdaderamente toda la clase entienda, y como ya han mencionado deja tareas cortas,los exámenes con él son de marcar con X. También es importante decir que es un profe que se identifica demasiado con el estudiante, es muy crack.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '172256ac3a7624bb21ace08568b56da9ca91f63b2e2e0c2624ecbd5c9187ab4c'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Se toma su tiempo para explicar a fondo cada tema, por lo que es muy muy claro. Además deja pequeñas tareas casi todas las semanas que lo mantienen a uno activo, practicando y ganando puntos fáciles, entnoces a uno se le pega mucho la materia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '147c57bf99a5afd4bd143d268159222d13ac0ab8ed8174ac82ac997004edc5b0'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Excelente profe, hace que las clases sean divertidasm las tareas ayudan a entender la teoria, y las progras soo faciles o dificiles nunca se sabe, pero el explica y ayuda si uno lo necesita, se nota que le gusta ser profesor, totalmente recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'cd7366f4e9bbab79464f1fc827ef3100465d6c429a089806a1f57cf884e03f08'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (293::BIGINT, 'Muy bueno como persona, pero en progras puede ser un arma de doble filo o puede ser muy fáciles o muy difíciles, los exámenes generalmente son muy fáciles. Y se que a el no le gusta que escriba esto pero bueno es mi opinión. (Las presentaciones me aburrían mucho)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-04-26T00:00:00+00:00'::TIMESTAMPTZ, '6891401cd4adc36fc9d00ebc9c7122bf789c56b467ecf3c9a10974b3d8c10f9b'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (293::BIGINT, 'Lo recomiendo, aunque de verdad se debe practicar la parte programada constantemente, ya que el profe se encarga más de lo teórico'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-28T00:00:00+00:00'::TIMESTAMPTZ, '6d686dd1de4347a81bf56e1b4c5201f396f4a973ab70701f403c125f266834f8'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-24T00:00:00+00:00'::TIMESTAMPTZ, '24b6d7e985836e87d67548b9cac22d8f7514d22c360ce6ff1dc24e28bebaae42'::TEXT, ARRAY[1020]::BIGINT[]),
    (293::BIGINT, 'De los mejores profes que he tenido, el mae es super buena nota y es uno de los pocos que de verdad se le nota el interes de que el estudiante verdaderamente aprenda. Super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-23T00:00:00+00:00'::TIMESTAMPTZ, '6958ac72779b179a1ca1c81fa446f98a96c069ee86afc245afbfd5c2ac8dcd0d'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-29T00:00:00+00:00'::TIMESTAMPTZ, '874a5f0229f0ee8fc80de9755992edd91ef23e3d1cd5e5a5431ab466a6fbdb44'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (293::BIGINT, 'Excelente profe!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'c3a2a283c89c9e9f3352f97d12650856e0ba835e68eeea33afdd345b1faf7ae8'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Muy buen profe con mucha paciencia y explica la materia muy bien. Intenta buscar la forma de hacer que los alumnos entiendan y atiende cualquier duda aunque esta sea muy absurda'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-24T00:00:00+00:00'::TIMESTAMPTZ, '0f963277ed7241953baea69c9036667602586e28bda0d3fd9e385c772490f74c'::TEXT, ARRAY[1020, 1022, 1030, 1029]::BIGINT[]),
    (293::BIGINT, 'Excelente profesor: se le entiende a la perfección, puntual, muy organizado, excelentes especificaciones a cuanto las progras. Ayuda muchisimo y esta disponible 24/7 (en serio), y el mae hace clases entretenidas. En cuanto al curso no es complicado. Muy recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-24T00:00:00+00:00'::TIMESTAMPTZ, '3c595de9ec3b4fae88ba9db2403321732fdcccbfbf0f5270b8ed00909cbd275a'::TEXT, ARRAY[1030]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '34ce6afab3d3c70adee8ffe3740daaa5e36e4a6837b0de3a53fff1a8f351e207'::TEXT, ARRAY[1020, 1022, 1029]::BIGINT[]),
    (293::BIGINT, 'Excelente Profe y persona, tiene una excelente manera de organizar e impartir la clase, se le entiende a la perfección, dispuesto a ayudar, exige lo necesario. Totalmente respetuoso y super organizado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'e4cd66e435029b7a19a79db8265e7903073ad08adf56a9f40e92e2ea402d9a97'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (293::BIGINT, 'De los mejores profes que he tenido, una persona preparada para dar clases y disfruta lo que hace. Se le entiende a la perfección todo, por sus técnicas para explicar. Sus proyectos no son complicados pero logran el objetivo, enseñar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '291c37b9805eb9d356138554b09d545bdbee1c00e7e169b371f27e6de24d65de'::TEXT, ARRAY[1020, 1022, 1029]::BIGINT[]),
    (293::BIGINT, 'Uno de los mejores profes, es un crack y conoce un montón. Se aprende muy bien y explica genial, como persona es excelente, 100% geek y no lo queda a uno, sino que ayuda y a uno le va muy bien. Las progras son regulares.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '671416f5d124fdbc3289e98e95f85594bbf7fca8423041e7e6ff2276b9417d9a'::TEXT, ARRAY[1029]::BIGINT[]),
    (293::BIGINT, 'Totalmente recomendado. Como profe es muy bueno, como persona es demasiado tuanis. No complica el curso demasiado ni deja cosas exageradas que sabe que nadie va a hacer. Es súper enérgico para dar la clase y no trata mal a nadie. Es muy reservado y respetuoso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'e66e3f700334081d0bf444c15d09f26956a2a6fe60e97a960bc393af091beb81'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (293::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'db52d6e7dc9123b126367f4e4890c6d8ca1f0b8f2d5fe7048c5ca496f9f00339'::TEXT, ARRAY[1029]::BIGINT[]),
