    (293::BIGINT, 'Excelente como profesor y como persona. A pesar de dejar trabajos sencillos y hasta dar ayudas en progras, explica de manera muy clara y buena los temas del curso. Llevé dos cursos con él y a veces sentí que hasta era demasiado fácil, pero igual entendí toda la materia con claridad.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'cb4b2402384d0e4cfa5785f8e32ecb98b8f7edb9cb69ef770b8c6a3425e904f7'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (293::BIGINT, 'Curso fácil, pero se aprende mucho y se entiende todo. Excelente profesor y muy buena técnica'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'e8e557a7ac7a693e54324e3fb72d677afaa0516456070377ad8ff719ceeec63a'::TEXT, ARRAY[1029]::BIGINT[]),
